<?php
declare(strict_types=1);
require __DIR__.'/app/bootstrap.php';
try {
 $user=Auth::user(); if(!$user) redirect(base_url('login.php'));
 if($user['role']==='OWNER' && $user['must_reset']) throw new AppError('Change your temporary password first.',403);
 $payment=null; $movement=null; $o=null; $items=[];
 if(!empty($_GET['return'])) {
    $movement=Auth::record('container_movements',whole($_GET['return'],1));
    if($movement['movement_type']!=='return') throw new AppError('Return receipt not found.',404);
    $customer=Auth::record('customers',(int)$movement['customer_id']); $branchId=(int)$movement['branch_id'];
    $reference=$movement['reference']; $date=$movement['created_at']; $actorId=(int)$movement['actor_id'];
 } else {
    if(!empty($_GET['payment'])) {
        $payment=Database::one('SELECT * FROM payments WHERE id=?',[whole($_GET['payment'],1)]);
        if(!$payment) throw new AppError('Payment not found.',404);
        $o=Auth::record('orders',(int)$payment['order_id']);
    } else $o=Auth::record('orders',whole($_GET['id'] ?? 0,1));
    $customer=$o['customer_id'] ? Auth::record('customers',(int)$o['customer_id']) : null;
    $items=Database::all('SELECT * FROM order_items WHERE order_id=? ORDER BY id',[$o['id']]);
    $branchId=(int)$o['branch_id']; $reference=$payment['receipt_number'] ?? $o['order_number'];
    $date=$payment['created_at'] ?? $o['created_at']; $actorId=(int)($payment['created_by'] ?? $o['created_by']);
 }
 $branch=Database::one('SELECT * FROM branches WHERE id=?',[$branchId]); $actor=Database::one('SELECT name FROM users WHERE id=?',[$actorId])['name'];
 $containerHistory=[];
 if($o) $containerHistory=Database::all('SELECT * FROM container_movements WHERE order_id=? ORDER BY id',[$o['id']]);
 $borrowed=0; $returned=0; foreach($containerHistory as $m) { if($m['movement_type']==='borrow') $borrowed+=(int)$m['quantity']; if($m['movement_type']==='return') $returned-= (int)$m['quantity']; }
 $ledgerDate=$containerHistory ? max($date,max(array_column($containerHistory,'created_at'))) : $date;
 $balanceAtReceipt=$customer ? (int)Database::one('SELECT COALESCE(SUM(quantity),0) n FROM container_movements WHERE customer_id=? AND (created_at<? OR (created_at=? AND id<=?))',[$customer['id'],$ledgerDate,$ledgerDate,$movement['id'] ?? ($containerHistory ? max(array_column($containerHistory,'id')) : 0)])['n'] : 0;
} catch(AppError $e) { http_response_code($e->httpStatus); exit(e($e->getMessage())); }
catch(Throwable $e) { error_log((string)$e); http_response_code(500); exit('Receipt could not be loaded.'); }
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($reference)?> · Aqua Rose</title><link rel="stylesheet" href="<?=e(base_url('assets/css/receipt.css'))?>"><script defer src="<?=e(base_url('assets/js/app.js'))?>"></script></head><body><div class="receipt-toolbar"><a href="<?=e(url($movement?'ledger':'orders'))?>">← Back to workspace</a><button data-print type="button">Print / Save PDF</button></div><main class="receipt"><header><img src="<?=e(base_url('assets/images/logo.svg'))?>" alt=""><h1><?=e(setting('station_name','AQUA ROSE'))?></h1><p><?=e(setting('tagline','Water Refilling Station'))?></p><strong><?=e($branch['name'])?></strong><?php if($branch['address']): ?><p><?=e($branch['address'])?></p><?php endif; if($branch['phone']): ?><p><?=e($branch['phone'])?></p><?php endif; ?></header><div class="rule"></div><h2><?= $movement?'GALLON RETURN RECEIPT':($payment?strtoupper($payment['direction']).' RECEIPT':'SALES INVOICE')?></h2><dl><div><dt>Reference</dt><dd><?=e($reference)?></dd></div><div><dt>Date</dt><dd><?=e(fmt_date($date,'Y-m-d g:i A'))?></dd></div><div><dt>Customer</dt><dd><?=e($customer['name'] ?? 'Walk-in customer')?></dd></div><?php if($customer && $customer['phone']): ?><div><dt>Contact</dt><dd><?=e($customer['phone'])?></dd></div><?php endif; ?><div><dt>Recorded by</dt><dd><?=e($actor)?></dd></div></dl><div class="rule"></div>
<?php if($movement): ?><div class="total-row"><span>Gallons returned</span><strong><?=abs((int)$movement['quantity'])?></strong></div><p>Condition: <?=e($movement['condition_status'])?></p><p><?=e($movement['notes'])?></p><div class="rule"></div><div class="total-row"><span>Balance after this return</span><strong><?=$balanceAtReceipt?> gal</strong></div>
<?php else: ?><p class="center"><?=e($o['order_number'])?> · <?=e(str_replace('_',' ',$o['order_type']))?></p><?php if($o['status']==='cancelled'): ?><h2>CANCELLED / VOIDED</h2><p><?=e($o['void_reason'])?></p><?php endif; ?><table><thead><tr><th>Item</th><th>Qty</th><th>Total</th></tr></thead><tbody><?php foreach($items as $i): ?><tr><td><?=e($i['name'])?><small>@ <?=peso($i['unit_price'])?></small></td><td><?=$i['quantity']?></td><td><?=peso($i['line_total'])?></td></tr><?php endforeach; ?></tbody></table><div class="rule"></div><dl><div><dt>Subtotal</dt><dd><?=peso($o['subtotal'])?></dd></div><?php if(cents($o['discount'])>0): ?><div><dt>Discount</dt><dd>−<?=peso($o['discount'])?></dd></div><?php endif; ?><?php if(cents($o['delivery_fee'])>0): ?><div><dt>Delivery fee</dt><dd><?=peso($o['delivery_fee'])?></dd></div><?php endif; ?></dl><div class="total-row"><span>INVOICE TOTAL</span><strong><?=peso($o['total'])?></strong></div><?php if($payment): ?><div class="rule"></div><dl><div><dt><?=ucfirst($payment['direction'])?> amount</dt><dd><?=peso($payment['amount'])?></dd></div><div><dt>Amount received / refunded</dt><dd><?=peso($payment['tendered'])?></dd></div><div><dt>Change</dt><dd><?=peso(decimal(cents($payment['tendered'])-cents($payment['amount'])))?></dd></div><div><dt>Method</dt><dd><?=e($payment['method'])?></dd></div><?php if($payment['reference']): ?><div><dt>Payment reference</dt><dd><?=e($payment['reference'])?></dd></div><?php endif; ?></dl><?php else: $orderPayments=Database::all("SELECT * FROM payments WHERE order_id=? AND direction='collection' ORDER BY id",[$o['id']]); ?><dl><?php foreach($orderPayments as $pay): ?><div><dt><?=e($pay['method'].' · '.$pay['receipt_number'])?></dt><dd><?=peso($pay['amount'])?></dd></div><?php endforeach; ?></dl><?php if(count($orderPayments)===1): $pay=$orderPayments[0]; ?><dl><div><dt>Amount received</dt><dd><?=peso($pay['tendered'])?></dd></div><div><dt>Change</dt><dd><?=peso(decimal(cents($pay['tendered'])-cents($pay['amount'])))?></dd></div></dl><?php endif; endif; ?><div class="total-row"><span>Current invoice balance</span><strong><?=peso($o['balance_due'])?></strong></div><p>Order status: <?=e(Sales::statusLabel($o))?></p>
<?php if($customer): ?><div class="rule"></div><h2>STATION CONTAINER LEDGER</h2><dl><div><dt>Borrowed on this order</dt><dd>+<?=$borrowed?> gal</dd></div><div><dt>Returned on this order</dt><dd>−<?=$returned?> gal</dd></div><div><dt>Balance after order custody</dt><dd><?=$balanceAtReceipt?> gal</dd></div><?php if($o['order_type']==='delivery' && !$containerHistory): ?><p>Planned: <?=$o['planned_borrowed']?> out / <?=$o['planned_returned']?> in. Posted on delivery.</p><?php endif; if($o['return_due_date']): ?><div><dt>Agreed return date</dt><dd><?=e($o['return_due_date'])?></dd></div><?php endif; ?></dl><?php endif; endif; ?><div class="rule"></div><footer><strong>Clean water. Clear care.</strong><p>Thank you for choosing Aqua Rose.</p><p>Keep this receipt for payment and gallon-return verification.</p><small>Computer-generated station record.<br>Printed <?=e(date('Y-m-d g:i A'))?> · Reprint values may reflect later payments.</small></footer></main></body></html>
